async function getDictText(text, from, to, axios, t, config) {
  var w = String(text || "").replace(/[\r\n]+/g, " ").trim();
  var safe = w.replace(/[&<>]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]; });
  try {
    var api = window.electronAPI;
    if (!api || !api.fs || !api.invoke) {
      return "<p>此插件需要 Koodo 桌面版。</p>";
    }
    var isWin = api.runtime && api.runtime.platform === "win32";
    if (!isWin) {
      return "<p>此插件只写了 Windows 的跳转逻辑。</p>";
    }
    var dir = api.path.join(api.os.homedir(), "AppData", "Local", "Temp");
    var file = api.path.join(dir, "koodo-goldendict-jump.url");
    var url = "goldendict://" + encodeURIComponent(w) + "?target=popup";
    api.fs.writeFileSync(file, "[InternetShortcut]\r\nURL=" + url + "\r\n", "utf8");
    await api.invoke("open-explorer-folder", { isFolder: true, path: file });
    return "<p>已在 GoldenDict 弹窗中打开：" + safe + "</p>";
  } catch (e) {
    return "<p>跳转失败：" + (e && e.message ? e.message : e) + "</p>";
  }
}
window.getDictText = getDictText;
